<script setup lang="ts">
import { computed,ref,watch } from 'vue'
import { useUiStore } from '../../stores/ui.store'
import { useTimerStore } from '../../stores/timer.store'
import { useRadioStore } from '../../stores/radio.store'
import IstanteIcon from '../IstanteIcon.vue'
const ui=useUiStore(),timer=useTimerStore(),radio=useRadioStore();const minutes=ref(Math.max(1,Math.round(timer.totalSeconds/60)));const now=ref(new Date());const nowText=computed(()=>now.value.toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'}));const running=computed(()=>timer.status==='running'||timer.status==='paused');function change(delta:number){minutes.value=Math.max(1,Math.min(180,minutes.value+delta));timer.setMinutes(minutes.value)}function setMode(mode:'silence'|'play'|'keep'){timer.radioMode=mode}function applyRadio(){if(timer.radioMode==='silence'||timer.radioMode==='stop')radio.pause();else if(timer.radioMode==='play'&&!radio.playing){radio.current?void radio.play(radio.current):radio.surprise()}}watch(()=>timer.radioMode,()=>{if(timer.status==='running')applyRadio()});function action(){if(timer.status==='running')timer.pause();else if(timer.status==='paused'){timer.resume();applyRadio()}else{timer.setMinutes(minutes.value);timer.start();applyRadio()}}function reset(){timer.reset();minutes.value=Math.max(1,Math.round(timer.totalSeconds/60))}
</script>
<template><Teleport to="body"><div v-if="ui.timerOpen" class="timer-backdrop" @click.self="ui.timerOpen=false"><section class="timer-panel" role="dialog" aria-modal="true" aria-labelledby="timer-title"><header class="panel-head"><div><p class="section-label">Prenditi un momento</p><h2 id="timer-title">Il tuo tempo.</h2><p class="timer-modal-now"><span>Adesso</span><strong>{{nowText}}</strong></p></div><button class="icon-button close" aria-label="Chiudi timer" @click="ui.timerOpen=false"><IstanteIcon name="close"/></button></header><div class="timer-content"><div class="timer-time-stage"><template v-if="!running"><span class="duration-label section-label">Quanto tempo vuoi tenerti?</span><div class="timer-dial-shell"><button class="timer-step-button" aria-label="Riduci di un minuto" @click="change(-1)">−</button><div class="timer-duration-dial"><div class="dial-track"/><div class="dial-center"><output>{{minutes}} <small>minuti</small></output></div></div><button class="timer-step-button" aria-label="Aumenta di un minuto" @click="change(1)">+</button></div><input v-model.number="minutes" class="duration-range" type="range" min="1" max="180" step="1" @input="timer.setMinutes(minutes)"/></template><template v-else><span class="duration-label section-label">{{timer.status==='running'?'Il tuo momento, in corso':'Il tuo momento, in pausa'}}</span><div class="timer-orbit" :style="{'--progress':`${timer.progress*360}deg`}"><div><strong>{{timer.formatted}}</strong><span>{{timer.status==='running'?'Resta qui.':'In pausa.'}}</span></div></div></template></div><div class="timer-session-options"><div class="timer-sound-segments" role="group" aria-label="Audio durante questa pausa"><button :aria-pressed="timer.radioMode==='silence'" @click="setMode('silence')"><span class="silence-dot">·</span>Silenzio</button><button :aria-pressed="timer.radioMode==='play'" @click="setMode('play')"><IstanteIcon name="headphones" :size="15"/>Radio</button><button :aria-pressed="timer.radioMode==='keep'" @click="setMode('keep')"><span class="music-note">≈</span>Suono relax</button></div><label class="finish-sound"><span>Suono alla fine</span><input v-model="timer.endSoundEnabled" type="checkbox"/></label></div></div><footer class="panel-footer"><button v-if="running" class="text-button" @click="reset">Annulla timer</button><span v-else/><button class="primary-button" @click="action"><IstanteIcon :name="timer.status==='running'?'pause':'play'" :size="16"/><span>{{timer.status==='running'?'Metti in pausa':timer.status==='paused'?'Riprendi il tuo momento':'Inizia il tuo momento'}}</span></button></footer></section></div></Teleport></template>
